\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Custom Medical Color Theme ──
\definecolor{primary}{HTML}{0A1E3D}      % deep navy
\definecolor{secondary}{HTML}{1C7B7A}    % muted teal
\definecolor{accent}{HTML}{CC5533}       % coral (risk flag)
\definecolor{bgposter}{HTML}{F4F7FA}     % cool light blue-white
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEE8E8} % warm stat highlight for risk

% Card background tints (NOT pure white)
\definecolor{bluebg}{HTML}{EEF4F6}       % cool blue tint
\definecolor{riskbg}{HTML}{FDF5F1}       % warm cream tint for risk cards
\definecolor{darkbg}{HTML}{F2F4F7}       % neutral tint for dark cards
\definecolor{bluetitlebg}{HTML}{DCE8EC}  % blue card title tint
\definecolor{risktitlebg}{HTML}{FBE8E0}  % risk card title tint
\definecolor{darktitlebg}{HTML}{E4E8EF}  % dark card title tint
\definecolor{statbluebg}{HTML}{E8F4F4}   % stat box blue tint

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  riskcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=riskbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=risktitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════
% TITLE BAR (rows 0–4, span=3)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=18pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.30},
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries Large Language Models in Medicine}\\[10pt]
  {\fontsize{44}{52}\selectfont\bfseries Opportunities, Risks, and the Path Forward}\\[16pt]
  {\fontsize{32}{40}\selectfont\color{white!75} A Comprehensive Review \quad$\bullet$\quad
   Medical AI \& Digital Health Conference 2024}\\[6pt]
  {\fontsize{26}{32}\selectfont\color{white!55} Published in \textit{Nature Medicine}, July 2023}
}

% ═══════════════════════════════════════════════════════════
% STATS BANNER (rows 4–6, span=3) — 4 headline metrics
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!25},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{statbluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{secondary} $>$90\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} GPT-4 USMLE Score}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} All 3 steps exceeded}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{statbluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{secondary} 500+}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} PubMed Articles (2023)}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Peer-reviewed publications}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent} Up to 30\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Hallucination Rate}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Fabricated clinical info}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{statbluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{secondary} \$10.5B}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Market Projection 2030}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Global healthcare LLM market}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════
% ROW A (rows 6–11): Overview | Applications | Performance
% ═══════════════════════════════════════════════════════════

% Col 1: Overview
\posterbox[darkcard, title={What Are LLMs and Why\\Do They Matter for Medicine?}
]{name=overview, column=1, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item Foundation models trained on vast text corpora — GPT-4, Med-PaLM 2, LLaMA
    \item Over \textbf{500 peer-reviewed publications} on LLMs in medicine appeared in 2023 alone
    \item Global healthcare LLM market projected to reach \textbf{\$10.5 billion by 2030}
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{30}{38}\selectfont\bfseries\color{primary} LLMs are poised to reshape clinical practice,}\\[2pt]
    {\fontsize{30}{38}\selectfont\bfseries\color{primary} biomedical research, and medical education.}
    \vspace{6pt}%
  }}
}

% Col 2: Applications
\posterbox[bluecard, title={Key Clinical \& Research Applications}
]{name=applications, column=2, between=row6 and row11}{
  \fontsize{30}{40}\selectfont
  \renewcommand{\arraystretch}{1.7}
  \begin{tabular}{p{0.54\linewidth} p{0.42\linewidth}}
    \textbf{Clinical Documentation} & \color{secondary!70}Pilot \\
    \small Automated notes, discharge summaries & \\
    \textbf{Diagnostic Support} & \color{secondary!70}Research \\
    \small Differential diagnosis, radiology reports & \\
    \textbf{Patient Communication} & \color{secondary!70}Early \\
    \small Answering questions, simplifying jargon & \\
    \textbf{Medical Education} & \color{secondary!70}Active \\
    \small Exam preparation, case-based tutoring & \\
    \textbf{Biomedical Research} & \color{secondary!70}Emerging \\
    \small Literature synthesis, hypothesis generation & \\
  \end{tabular}
  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{5pt}
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary} Clinical documentation \& patient communication}
    {\fontsize{28}{36}\selectfont\color{textdark} tools have seen the fastest real-world adoption.}
    \vspace{5pt}%
  }}
}

% Col 3: Performance
\posterbox[bluecard, title={Performance Benchmarks \& Evidence}
]{name=performance, column=3, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item \textbf{GPT-4} scored \textcolor{secondary}{\textbf{$>$90\%}} on all three USMLE steps — substantially above the $\sim$60\% passing threshold
    \item \textbf{Med-PaLM 2} achieved \textbf{86.5\%} on MedQA, approaching expert physician performance
    \item \textbf{GPT-3.5} scored near the passing threshold ($\sim$60\%) but fell short on complex clinical reasoning
  \end{itemize}
  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{5pt}
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary} LLMs encode substantial medical knowledge,}
    {\fontsize{28}{36}\selectfont\color{textdark} but real-world clinical performance remains less well characterized.}
    \vspace{5pt}%
  }}
}

% ═══════════════════════════════════════════════════════════
% ROW B (rows 11–17): Risks Part 1 | Risks Part 2 | Why Risk Matters
% ═══════════════════════════════════════════════════════════

% Col 1: Risks — Hallucinations & Bias
\posterbox[riskcard, title={Risks \& Limitations:\\Hallucinations \& Bias}
]{name=risks1, column=1, between=row11 and row17}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item \textbf{Hallucinations}: LLMs fabricate plausible-sounding but incorrect medical information, including fake citations. Studies report hallucination rates of \textcolor{accent}{\textbf{up to 30\%}} in medical Q\&A tasks.
    \item \textbf{Bias \& Equity}: Models may perpetuate or amplify biases from training data, leading to disparities in care recommendations across demographic groups.
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{5pt}
    {\fontsize{28}{36}\selectfont\bfseries\color{accent} $\blacktriangleright$ Fabricated references pose direct}
    {\fontsize{28}{36}\selectfont\bfseries\color{accent} patient safety risks in clinical settings.}
    \vspace{5pt}%
  }}
}

% Col 2: Risks — Privacy, Validation, Over-reliance
\posterbox[riskcard, title={Risks \& Limitations:\\Privacy, Validation \& Over-Reliance}
]{name=risks2, column=2, between=row11 and row17}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item \textbf{Privacy}: Patient data in prompts may be transmitted to external servers, raising \textbf{HIPAA and GDPR} compliance concerns.
    \item \textbf{Lack of Clinical Validation}: Most evaluations rely on \textbf{multiple-choice benchmarks} rather than prospective clinical trials.
    \item \textbf{Over-Reliance Risk}: Clinicians may develop \textbf{automation bias}, accepting LLM outputs without sufficient critical appraisal.
  \end{itemize}
}

% Col 3: Why Risk Matters
\posterbox[darkcard, title={Why These Risks Matter}
]{name=risks3, column=3, between=row11 and row17}{
  \fontsize{34}{44}\selectfont
  \vspace{8pt}
  \colorbox{accent!15}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{32}{40}\selectfont\bfseries\color{accent} The Gap Problem}
    \vspace{4pt}
    \begin{itemize}[itemsep=8pt, leftmargin=18pt]
      \item Benchmark performance $\neq$ clinical safety
      \item $>$90\% exam scores coexist with 30\% hallucination rates
      \item No prospective clinical trials have validated LLM deployment
    \end{itemize}
    \vspace{4pt}%
  }}
  \vspace{10pt}
  \colorbox{primary!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{32}{40}\selectfont\bfseries\color{primary} The central challenge:}
    \vspace{4pt}
    {\fontsize{30}{38}\selectfont\color{textdark} Bridging the gap between impressive benchmark results and safe, equitable clinical deployment.}
    \vspace{6pt}%
  }}
}

% ═══════════════════════════════════════════════════════════
% ROW C (rows 17–bottom): Framework (span=3)
% ═══════════════════════════════════════════════════════════
\posterbox[highlightcard, title={A Framework for Responsible Deployment}
]{name=framework, column=1, span=3, between=row17 and bottom}{
  \fontsize{32}{42}\selectfont
  \centering
  \vspace{4pt}
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{white}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 1}\\[4pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{primary} Rigorous\\Prospective\\Evaluation}
      \vspace{4pt}
      {\fontsize{24}{32}\selectfont\color{textgray} Diverse clinical settings before deployment}
      \vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{white}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 2}\\[4pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{primary} Human-in-the-\\Loop Design}
      \vspace{4pt}
      {\fontsize{24}{32}\selectfont\color{textgray} Clinician oversight of all LLM-generated outputs}
      \vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{white}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 3}\\[4pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{primary} Transparent\\Reporting}
      \vspace{4pt}
      {\fontsize{24}{32}\selectfont\color{textgray} Model limitations, training data, failure modes}
      \vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{white}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 4}\\[4pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{primary} Equity\\Audits}
      \vspace{4pt}
      {\fontsize{24}{32}\selectfont\color{textgray} Differential performance across patient populations}
      \vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \colorbox{white}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}
      {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 5}\\[4pt]
      {\fontsize{28}{36}\selectfont\bfseries\color{primary} Regulatory\\Alignment}
      \vspace{4pt}
      {\fontsize{24}{32}\selectfont\color{textgray} FDA, EMA, WHO guidance on AI medical devices}
      \vspace{8pt}%
    }}
  \end{minipage}
  \vspace{6pt}
}

\end{tcbposter}
\end{document}

